{
  "tasks": [
    {
      "task_id": "T1",
      "title": "2026年华东地区已完成订单销售额城市排名Top3",
      "business_question": "在2026年、华东地区且状态为“已完成”的订单中，各城市的销售额总和是多少？按销售额降序排列取前三名。",
      "priority": "P0",
      "priority_reason": "直接回答核心分析目标，缺失则无法完成决策支持。包含时间、地域、状态筛选及指标聚合排序，所有约束均为必要步骤。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04",
        "C05"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "gte",
                "value": "2026-01-01"
              },
              {
                "field": "field_0001",
                "operator": "lt",
                "value": "2027-01-01"
              },
              {
                "field": "field_0002",
                "operator": "eq",
                "value": "华东地区"
              },
              {
                "field": "field_0004",
                "operator": "eq",
                "value": "已完成"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0005",
                "alias": "total_sales"
              }
            ],
            "dimensions": [
              "field_0003"
            ]
          }
        },
        {
          "step_id": "S3",
          "operation": "top_n",
          "params": {
            "field": "total_sales",
            "direction": "desc",
            "n": 3
          }
        }
      ]
    }
  ]
}
